const x=$input.first().json;const user=x.user||{};const chat=x.chat||{};
const message=String(x.message??x.chatInput??'').trim();
const groups=Array.isArray(x.groups)?x.groups.filter(v=>typeof v==='string').slice(0,100):[];
const username=String(user.username??'').trim();const email=String(user.email??'').trim();
const chatId=String(chat.chat_id??x.sessionId??'').trim();
