const x=$input.first().json;const missing=[];
if(!x.id_token||typeof x.id_token!=='string')missing.push('id_token');
if(!x.user?.username)missing.push('user.username');
if(!x.user?.email)missing.push('user.email');
if(!x.message)missing.push('message');
if(!x.chat?.chat_id)missing.push('chat.chat_id');
if(missing.length)throw Error('Missing required identity/chat fields: '+missing.join(', '));
// NOTE: This is shape validation ONLY. JWT signature/issuer/audience/expiry MUST be verified by trusted upstream auth.
return [{json:{...x,identity_valid:true,session_key:x.user.email+'::'+x.chat.chat_id}}];

const raw=$input.first().json.output??$input.first().json.text??'';
let d;try{if(typeof raw==='string'){const s=raw.trim().replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/,'');try{d=JSON.parse(s)}catch{const start=s.indexOf('{'),end=s.lastIndexOf('}');if(start<0||end<=start)throw Error('bad json');d=JSON.parse(s.slice(start,end+1));}}else d=raw;if(!d||typeof d!=='object'||Array.isArray(d))throw Error('bad object');}catch{return [{json:{responseType:'text',answer:String(raw||'AI 沒有回傳有效 JSON')}}]}
const answer=String(d.answer??'');
if(d.responseType==='dashboard_panel'&&d.panel&&typeof d.panel==='object'){const p=d.panel;return [{json:{responseType:'dashboard_panel',answer,dashboardUid:p.dashboardUid,panelId:p.panelId,title:p.title||'Grafana Panel',from:p.from||'now-15m',to:p.to||'now',variables:p.variables??{}}}]}
if(d.responseType==='metric_chart'&&d.chart&&typeof d.chart==='object'){const p=d.chart;return [{json:{responseType:'metric_chart',answer,datasourceUid:p.datasourceUid,query:p.query,title:p.title||'Metrics 圖表',from:p.from||'now-15m',to:p.to||'now'}}]}
return [{json:{responseType:'text',answer:answer||'沒有取得可確認的查詢結果。'}}];

const d=$input.first().json;const BASE='https://utckfk8sgrafana.k8skf.unimicron.com';
const uid=String(d.dashboardUid||'').trim(),panelId=Number(d.panelId);if(!/^[A-Za-z0-9_-]+$/.test(uid)||!Number.isSafeInteger(panelId)||panelId<=0)throw Error('Dashboard UID 或 Panel ID 無效');
const from=String(d.from||'now-15m'),to=String(d.to||'now');
function parse(v){if(v==='now')return Date.now();const m=/^now-(\d+)([smhdw])$/.exec(v);if(m)return Date.now()-Number(m[1])*({s:1e3,m:6e4,h:36e5,d:864e5,w:6048e5}[m[2]]);if(!/(Z|[+-]\d\d:\d\d)$/i.test(v))throw Error('絕對時間必須包含時區');const n=Date.parse(v);if(!Number.isFinite(n))throw Error('時間格式不合法');return n;}
const start=parse(from),end=parse(to);if(end<=start||end-start>7*864e5||end>Date.now()+6e4)throw Error('查詢時間範圍不合法');
const vars=d.variables??{};if(!vars||typeof vars!=='object'||Array.isArray(vars)||Object.keys(vars).length>30)throw Error('Variables 不合法');
const enc=encodeURIComponent;let varsQuery='';for(const [rawKey,rawValue] of Object.entries(vars)){const key=rawKey.replace(/^var-/,'');if(!/^[A-Za-z_][A-Za-z0-9_-]*$/.test(key))throw Error('Variable 名稱不合法');for(const v of Array.isArray(rawValue)?rawValue:[rawValue]){if(typeof v!=='string'||v.length>300)throw Error('Variable 值不合法');varsQuery+='&var-'+enc(key)+'='+enc(v);}}
const common='?orgId=1&from='+enc(from)+'&to='+enc(to);
const renderUrl=BASE+'/render/d-solo/'+enc(uid)+common+'&panelId='+panelId+'&width=1200&height=650&theme=dark&timeout=120&tz='+enc('Asia/Taipei')+varsQuery;
const dashboardUrl=BASE+'/d/'+enc(uid)+common+'&timezone='+enc('Asia/Taipei')+varsQuery;
return [{json:{...d,from,to,start,end,renderUrl,dashboardUrl}}];

const i=$input.first();if(!i.binary?.data)throw Error('Grafana Renderer 沒有回傳 Binary data');const b=await this.helpers.getBinaryDataBuffer(0,'data');if(b.subarray(0,8).toString('hex')!=='89504e470d0a1a0a')throw Error('Renderer 回傳不是 PNG');
const p=$('Validate Panel & Build URLs').first().json;const tw=v=>new Date(v).toLocaleString('zh-TW',{timeZone:'Asia/Taipei',hour12:false});
const out=['### '+String(p.title||'Grafana Panel'),String(p.answer||''),'![Grafana Panel](data:image/png;base64,'+b.toString('base64')+')','**查詢時間（台灣）：** '+tw(p.start)+' ～ '+tw(p.end),'[開啟 Grafana Dashboard]('+p.dashboardUrl+')'];return [{json:{output:out.filter(Boolean).join('\n\n')}}];
